/**
 * The three orientations the unit points its selector triangle, as transforms
 * of the one entry that holds it.
 *
 * `interface.down` is the drawing; these place it. Both transforms are exact
 * on the stored coordinates, which is the point of storing the mark
 * hard-cornered: a quarter turn of `M5.04 8L18.96 8L12 17.02Z` about the box
 * centre lands on whole hundredths, so up and right are the same three
 * numbers rather than two more traces to keep in step.
 *
 *   up    rotate 180 about (12,12)  -> M18.96 16L5.04 16L12 6.98Z
 *   right rotate -90 about (12,12)  -> M8 18.96L8 5.04L17.02 12Z
 *
 * The one datum that is not a rotation is `right`'s single-pixel shift: the
 * storage row's own layout holds the mark one pixel left and one pixel down
 * of where a quarter turn alone would put it, and that offset is a whole
 * pixel, not a fit.
 */
/**
 * The other direction of the scene shuttle, as a transform of the one entry
 * that holds it.
 *
 * `editor.scene-next` is the drawing. Turned over about the centre of its
 * 30x24 box, it is a rotation rather than a second drawing that happens to
 * look reversed.
 */
export const QC_SCENE_SHUTTLE_REVERSE = "rotate(180 15 12)";

export const QC_SELECTOR_TRIANGLE_TRANSFORMS = {
  down: undefined,
  up: "rotate(180 12 12)",
  right: "translate(-1 1) rotate(-90 12 12)"
} as const;
export type QcSelectorTriangleOrientation = keyof typeof QC_SELECTOR_TRIANGLE_TRANSFORMS;
